script:
frappe.ui.form.on("NDIS Participant Intake", {
    refresh(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button(__("Create CRM Deal"), function () {
                frappe.call({
                    method: "ndis_crm.phase2_api.create_crm_deal_from_intake",
                    args: {
                        intake: frm.doc.name
                    },
                    freeze: true,
                    freeze_message: __("Creating CRM Deal...")
                }).then((r) => {
                    if (r.message && r.message.name) {
                        frappe.show_alert({
                            message: r.message.created ? __("CRM Deal created") : __("Existing CRM Deal found"),
                            indicator: "green"
                        });

                        frm.reload_doc();

                        frappe.set_route("Form", "CRM Deal", r.message.name);
                    }
                });
            }, __("Actions"));
        }
    }
});

frappe.ui.form.on("NDIS CRM Finance Onboarding", {
    refresh(frm) {
        if (frm.is_new()) {
            return;
        }

        frm.add_custom_button(__("Create / Link Financial Profile"), function () {
            frappe.call({
                method: "ndis_crm.phase5_finance_onboarding.create_financial_profile_from_onboarding",
                args: {
                    onboarding: frm.doc.name
                },
                freeze: true,
                freeze_message: __("Creating or linking financial profile...")
            }).then((r) => {
                if (r.message) {
                    frappe.show_alert({
                        message: r.message.message || __("Financial Profile linked"),
                        indicator: "green"
                    });
                    frm.reload_doc();
                }
            });
        }, __("Actions"));

        frm.add_custom_button(__("Validate Finance Readiness"), function () {
            frappe.call({
                method: "ndis_crm.phase5_finance_onboarding.validate_finance_onboarding_readiness",
                args: {
                    onboarding: frm.doc.name
                },
                freeze: true,
                freeze_message: __("Validating finance readiness...")
            }).then((r) => {
                if (r.message) {
                    frappe.show_alert({
                        message: r.message.message || __("Finance readiness validated"),
                        indicator: "green"
                    });
                    frm.reload_doc();
                }
            });
        }, __("Actions"));

        frm.add_custom_button(__("Mark Ready for Finance"), function () {
            frappe.call({
                method: "ndis_crm.phase5_finance_onboarding.mark_ready_for_finance",
                args: {
                    onboarding: frm.doc.name
                },
                freeze: true,
                freeze_message: __("Marking ready for finance...")
            }).then((r) => {
                if (r.message) {
                    frappe.show_alert({
                        message: r.message.message || __("Ready for Finance"),
                        indicator: "green"
                    });
                    frm.reload_doc();
                }
            });
        }, __("Actions"));

        frm.add_custom_button(__("Create Draft Plan Budgets"), function () {
            frappe.call({
                method: "ndis_crm.phase6_finance_drafts.create_draft_plan_budgets_from_onboarding",
                args: {
                    onboarding: frm.doc.name
                },
                freeze: true,
                freeze_message: __("Creating draft plan budgets...")
            }).then((r) => {
                if (r.message) {
                    frappe.show_alert({
                        message: r.message.message || __("Draft plan budgets created"),
                        indicator: "green"
                    });
                    frm.reload_doc();
                }
            });
        }, __("Finance Records"));

        frm.add_custom_button(__("Create Service Bookings"), function () {
            frappe.confirm(
                __("This will create Active NDIS Service Booking records. Continue only after finance approval."),
                function () {
                    frappe.call({
                        method: "ndis_crm.phase6_finance_drafts.create_service_bookings_from_onboarding",
                        args: {
                            onboarding: frm.doc.name
                        },
                        freeze: true,
                        freeze_message: __("Creating service bookings...")
                    }).then((r) => {
                        if (r.message) {
                            frappe.show_alert({
                                message: r.message.message || __("Service bookings created"),
                                indicator: "green"
                            });
                            frm.reload_doc();
                        }
                    });
                }
            );
        }, __("Finance Records"));

        frm.add_custom_button(__("Recalculate Finance Records"), function () {
            frappe.call({
                method: "ndis_crm.phase6_finance_drafts.recalculate_finance_record_summary",
                args: {
                    onboarding: frm.doc.name
                },
                freeze: true,
                freeze_message: __("Recalculating finance records...")
            }).then((r) => {
                if (r.message) {
                    frappe.show_alert({
                        message: r.message.message || __("Finance records recalculated"),
                        indicator: "green"
                    });
                    frm.reload_doc();
                }
            });
        }, __("Finance Records"));

        frm.add_custom_button(__("Open Plan Budgets"), function () {
            frappe.route_options = {
                ndis_crm_finance_onboarding: frm.doc.name
            };
            frappe.set_route("List", "NDIS Plan Budget");
        }, __("Open"));

        frm.add_custom_button(__("Open Service Bookings"), function () {
            frappe.route_options = {
                ndis_crm_finance_onboarding: frm.doc.name
            };
            frappe.set_route("List", "NDIS Service Booking");
        }, __("Open"));

        frm.add_custom_button(__("Mark Finance Setup Complete"), function () {
            frappe.call({
                method: "ndis_crm.phase5_finance_onboarding.mark_finance_setup_complete",
                args: {
                    onboarding: frm.doc.name
                },
                freeze: true,
                freeze_message: __("Completing finance setup...")
            }).then((r) => {
                if (r.message) {
                    frappe.show_alert({
                        message: r.message.message || __("Finance setup completed"),
                        indicator: "green"
                    });
                    frm.reload_doc();
                }
            });
        }, __("Actions"));

        if (frm.doc.handover) {
            frm.add_custom_button(__("Open Handover"), function () {
                frappe.set_route("Form", "NDIS CRM Handover", frm.doc.handover);
            }, __("Open"));
        }

        if (frm.doc.crm_deal) {
            frm.add_custom_button(__("Open CRM Deal"), function () {
                window.open(`/crm/deals/${frm.doc.crm_deal}`, "_blank");
            }, __("Open"));
        }

        if (frm.doc.ndis_financial_profile) {
            frm.add_custom_button(__("Open Financial Profile"), function () {
                frappe.set_route("Form", "NDIS Participant Financial Profile", frm.doc.ndis_financial_profile);
            }, __("Open"));
        }
    }
});

frappe.ui.form.on("NDIS CRM Handover", {
    refresh(frm) {
        if (frm.is_new()) {
            return;
        }

        frm.add_custom_button(__("Create / Link Customer"), function () {
            frappe.call({
                method: "ndis_crm.phase4_handover.create_customer_from_handover",
                args: {
                    handover: frm.doc.name
                },
                freeze: true,
                freeze_message: __("Creating or linking Customer...")
            }).then((r) => {
                if (r.message) {
                    frappe.show_alert({
                        message: r.message.message || __("Customer linked"),
                        indicator: "green"
                    });
                    frm.reload_doc();
                }
            });
        }, __("Actions"));

        frm.add_custom_button(__("Create NDIS Financial Profile"), function () {
            frappe.call({
                method: "ndis_crm.phase4_handover.create_financial_profile_from_handover",
                args: {
                    handover: frm.doc.name
                },
                freeze: true,
                freeze_message: __("Creating NDIS Financial Profile...")
            }).then((r) => {
                if (r.message) {
                    frappe.show_alert({
                        message: r.message.message || __("NDIS Financial Profile linked"),
                        indicator: "green"
                    });
                    frm.reload_doc();
                }
            });
        }, __("Actions"));

        frm.add_custom_button(__("Recalculate Readiness"), function () {
            frappe.call({
                method: "ndis_crm.phase4_handover.recalculate_handover_readiness",
                args: {
                    handover: frm.doc.name
                },
                freeze: true,
                freeze_message: __("Recalculating handover readiness...")
            }).then((r) => {
                if (r.message) {
                    frappe.show_alert({
                        message: r.message.message || __("Readiness recalculated"),
                        indicator: "green"
                    });
                    frm.reload_doc();
                }
            });
        }, __("Actions"));

        frm.add_custom_button(__("Mark Ready for Operations"), function () {
            frappe.call({
                method: "ndis_crm.phase4_handover.mark_handover_ready",
                args: {
                    handover: frm.doc.name
                },
                freeze: true,
                freeze_message: __("Marking handover ready...")
            }).then((r) => {
                if (r.message) {
                    frappe.show_alert({
                        message: r.message.message || __("Handover ready"),
                        indicator: "green"
                    });
                    frm.reload_doc();
                }
            });
        }, __("Actions"));

        if (frm.doc.crm_deal) {
            frm.add_custom_button(__("Open CRM Deal"), function () {
                window.open(`/crm/deals/${frm.doc.crm_deal}`, "_blank");
            }, __("Open"));
        }
    },

    checklist_items_on_form_rendered(frm) {
        frm.trigger("set_completed_defaults");
    },

    set_completed_defaults(frm) {
        let row = frm.open_grid_row && frm.open_grid_row.doc;
        if (!row) {
            return;
        }

        if (row.status === "Completed" && !row.completed_on) {
            row.completed_on = frappe.datetime.now_datetime();
            row.completed_by = frappe.session.user;
            frm.refresh_field("checklist_items");
        }
    }
});
